+/*
+ * A nav group is the same disclosure pattern as the mobile nav-drawer,
+ * repeated per section instead of once for the whole menu: native
+ * <details>, no script, a dropdown positioned under its own summary rather
+ * than the page corner.
+ */
+.nav-group {
+  position: relative;
+}
+
+.nav-group summary {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.3em;
+  list-style: none;
+  cursor: pointer;
+  padding-block: 0.25rem;
+}
+
+.nav-group summary::-webkit-details-marker {
+  display: none;
+}
+
+.nav-group summary::after {
+  content: '';
+  width: 0;
+  height: 0;
+  border-inline: 0.3em solid transparent;
+  border-top: 0.35em solid currentcolor;
+}
+
+.nav-group summary:hover {
+  color: var(--accent);
+}
+
